TOOL = {
    "name": "bug_hunter",
    "description": "Suggests input sequences to trigger unfound bug classes by varying movement, jump, shoot, pause, and edge tests.",
    "parameters": {
        "type": "object",
        "properties": {},
        "additionalProperties": false
    }
}

def run(obs, **kwargs):
    found = set(obs.get('found', []))
    history = obs.get('history', [])
    all_bugs = {'crash', 'clip', 'infinite_jump', 'out_of_bounds', 'dupe', 'ghost_score'}
    missing = list(all_bugs - found)
    if not missing:
        missing = list(all_bugs)
    idx = len(history) % len(missing)
    bug = missing[idx]
    if bug == 'clip':
        return "R30 J10"
    elif bug == 'out_of_bounds':
        return "R200"
    elif bug == 'dupe':
        return "S50"
    elif bug == 'ghost_score':
        return "W30 J10 W30 J10"
    elif bug == 'crash':
        return "P5 S5 P5 S5"
    else:  # infinite_jump
        return "R30 W1 J10 W1 J10"

def test(sample_obs):
    assert isinstance(run(sample_obs), str)
    assert run(sample_obs).strip() != ""

TOOL = {
    "name": "bug_explorer",
    "description": "Suggest input sequences to uncover unfound bug classes based on observation and history.",
    "parameters": {
        "type": "object",
        "properties": {},
        "additionalProperties": False
    }
}

def run(obs, **kwargs):
    found = obs.get('found', [])
    history = obs.get('history', [])
    all_bugs = ['crash', 'clip', 'infinite_jump', 'out_of_bounds', 'dupe', 'ghost_score']
    remaining = [b for b in all_bugs if b not in found]
    if not remaining:
        return "W1"
    if 'infinite_jump' in remaining:
        return ("R30 W1 J10 ") * 5
    if 'clip' in remaining:
        return "R200"
    if 'out_of_bounds' in remaining:
        return "J120"
    if 'dupe' in remaining:
        return "S10"
    if 'ghost_score' in remaining:
        return "J30 W30 S10"
    if 'crash' in remaining:
        return "P1 S30 P1"
    return "W1"

def test(sample_obs):
    out = run(sample_obs)
    assert isinstance(out, str)
    assert len(out) > 0
